<?php if(!$admin&&$v&&$v['status']==='published'):$publicId=db()->prepare('SELECT public_id FROM businesses WHERE id=?');$publicId->execute([$business]);?><p class="notice" role="status">Tu publicación ya está visible en el portal. <a href="/negocios/<?=esc($publicId->fetchColumn())?>/">Ver mi publicación</a></p><?php endif ?><?php if($v):?><form method="post" class="registration-form editorial-actions"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="version_id" value="<?=(int)$v['id']?>"><input type="hidden" name="payload_hash" value="<?=esc($v['payload_hash'])?>"><?php if($admin&&$v['status']==='in_editorial'):?><fieldset><legend>Revisión editorial obligatoria del portal</legend><?php foreach(['translations'=>'Revisé todos los textos en español, inglés y portugués.','images'=>'Revisé la fidelidad, los permisos, el estilo y la calidad de las imágenes cuando aplican.','layout'=>'Revisé la página y la tarjeta, incluidos sus enlaces y presentación en móvil.'] as $reviewCode=>$reviewLabel):?><label class="registration-consent"><input type="checkbox" name="quality[<?=$reviewCode?>]" value="1" required><span><?=esc($reviewLabel)?></span></label><?php endforeach ?></fieldset><button class="pill" name="action" value="prepare">Preparar y enviar prepublicación al comerciante</button><?php elseif($admin&&$v['status']==='awaiting_owner'):?><button class="pill" name="action" value="notify">Notificar prepublicación por correo</button><?php elseif(!$admin&&$v['status']==='awaiting_owner'):?><p id="revision">Comprueba tu tarjeta y página en las vistas previas. Al aprobar, el portal revisará el pago y hará la publicación final.</p><button class="pill" name="action" value="approve">Aprobar prepublicación</button><label>Qué deseas corregir<textarea name="note" maxlength="2000" rows="3"></textarea></label><button class="pill light" name="action" value="request_changes">Solicitar correcciones</button><?php elseif($admin&&$v['status']==='owner_approved'):?><button class="pill" name="action" value="publish">Validar y publicar esta versión aprobada</button><?php endif ?><?php if($admin&&in_array($v['status'],['in_editorial','awaiting_owner','owner_approved'],true)):?><label>Motivo de rechazo<textarea name="note" maxlength="2000" rows="3"></textarea></label><button class="pill light" name="action" value="reject" formnovalidate>Rechazar esta versión e informar el motivo</button><?php endif ?></form><?php endif ?><?php endif ?></section></main><?php require dirname(__DIR__).'/_business-map-dialog.php';?><script src="/assets/leaflet.js"></script><script src="/assets/admin-business-location.js?v=17" defer></script><script src="<?=esc(admin_asset('business-editorial.js'))?>" defer></script><script src="/assets/account-files.js?v=1" defer></script></body></html>
